import math
import numpy as np

def _wilson(x, n, z=1.959964):
    ph = x / n
    denom = 1 + z**2 / n
    centre = (ph + z**2 / (2 * n)) / denom
    half = z / denom * math.sqrt(ph * (1 - ph) / n + z**2 / (4 * n**2))
    return (max(0.0, centre - half), min(1.0, centre + half))

def _wald(x, n, z=1.959964):
    ph = x / n
    half = z * math.sqrt(ph * (1 - ph) / n)
    return (ph - half, ph + half)

